def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    out = np.zeros((h * h, w * w), dtype=int)
    emit(out, f"Allocate a {h*h}x{w*w} canvas of 0s: a {h}x{w} arrangement of blocks, each the size of the input.")
    for i in range(h):
        for j in range(w):
            if g[i, j] == 5:
                out[i*h:(i+1)*h, j*w:(j+1)*w] = g
                emit(out, f"Input cell ({i},{j}) is 5, so stamp a copy of the whole input into block ({i},{j}).")
    emit(out, "Every 5-cell of the input now has a copy in its block; all other blocks stay 0.")
    return out
